import java.time.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class OrderService {
    private final OrderRepository repo;
    private final Clock clock; // injected -> Repeatable
    OrderService(OrderRepository repo, Clock clock) { this.repo = repo; this.clock = clock; }

    Order placeOrder(Long userId, String item) {
        return repo.save(new Order(userId, item, LocalDateTime.now(clock)));
    }
}

class OrderServiceTest {
    @Test
    void placeOrder_whenCalled_thenStampsTheFixedTime() {
        var fixedTime = LocalDateTime.of(2024, 1, 15, 10, 30);
        var clock = Clock.fixed(fixedTime.toInstant(ZoneOffset.UTC), ZoneOffset.UTC);
        var repo = mock(OrderRepository.class);
        when(repo.save(any())).thenAnswer(inv -> inv.getArgument(0));
        var service = new OrderService(repo, clock);

        Order saved = service.placeOrder(100L, "Laptop");

        assertEquals(fixedTime, saved.getTimestamp()); // Repeatable: time is controlled
    }
}
