import java.util.List;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class PriceCalculator {
    public double calculateSubtotal(List<Item> items) {
        double total = 0;
        for (Item item : items) {
            total += item.getPrice() * item.getQuantity();
        }
        return total;
    }
}

class PriceCalculatorTest {
    @Test
    void calculateSubtotal_whenMultipleItems_thenSumsPriceTimesQuantity() {
        var calculator = new PriceCalculator();
        var items = List.of(new Item("Laptop", 1000, 2), new Item("Mouse", 25, 3));

        double result = calculator.calculateSubtotal(items); // public method, no reflection

        assertEquals(2075.0, result);
    }
}
