import java.time.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

// FIXED: inject Clock instead of calling now() directly
public class PromotionService {
    private final Clock clock;
    public PromotionService(Clock clock) { this.clock = clock; }

    public boolean isPromotionActive(LocalDateTime start, LocalDateTime end) {
        var now = LocalDateTime.now(clock); // controllable in tests
        return now.isAfter(start) && now.isBefore(end);
    }
}

class PromotionServiceTest {
    @Test
    void isPromotionActive_whenWithinWindow_thenReturnsTrue() {
        var promoTime = LocalDateTime.of(2024, 12, 25, 12, 0);
        var clock = Clock.fixed(promoTime.toInstant(ZoneOffset.UTC), ZoneOffset.UTC);
        var service = new PromotionService(clock);

        boolean result = service.isPromotionActive(
            promoTime.minusHours(1), promoTime.plusHours(1));

        assertTrue(result); // always deterministic
    }
}
