import java.time.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class SubscriptionService {
    private final SubscriptionRepository repo;
    private final Clock clock;
    SubscriptionService(SubscriptionRepository repo, Clock clock) {
        this.repo = repo;
        this.clock = clock;
    }

    boolean isSubscriptionActive(Long userId) {
        var subscription = repo.findByUserId(userId);
        return Instant.now(clock).isBefore(subscription.expiryInstant());
    }
}

// Production: @Bean Clock clock() { return Clock.systemUTC(); }

class SubscriptionServiceTest {
    @Test
    void isSubscriptionActive_whenBeforeExpiry_thenReturnsTrue() {
        var now = Instant.parse("2024-12-26T12:00:00Z");
        var expiry = Instant.parse("2024-12-31T23:59:00Z");
        var clock = Clock.fixed(now, ZoneOffset.UTC);
        var repo = mock(SubscriptionRepository.class);
        when(repo.findByUserId(100L)).thenReturn(new Subscription(expiry));
        var service = new SubscriptionService(repo, clock);

        assertTrue(service.isSubscriptionActive(100L));
    }
}
